{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "يقول الرب: «أنا أخرجت هذا الشعب من العبودية، وأعطيتهم وصاياي على يد عبيدي الأنبياء، الذين لم يسمعوا لهم، بل أبطلوا مشورتي.",
      "chapter": 2,
      "verse": 1
    },
    {
      "text_ar": "تقول لهم الأم التي ولدتهم: ’امضوا يا أبنائي، فإني أرملة ومتروكة.",
      "chapter": 2,
      "verse": 2
    },
    {
      "text_ar": "لقد ربيتكم بفرح، وفقدتكم بحزن وعناء، لأنكم أخطأتم أمام الرب الإله، وفعلتم الشر أمامي.",
      "chapter": 2,
      "verse": 3
    },
    {
      "text_ar": "ولكن الآن، ماذا يمكنني أن أفعل لكم؟ فإني أرملة ومتروكة. امضوا يا أبنائي، واطلبوا الرحمة من الرب.’",
      "chapter": 2,
      "verse": 4
    },
    {
      "text_ar": "أما أنا، أيها الأب، فأدعوكم شهوداً مع أم هؤلاء الأولاد، لأنهم لم يحفظوا عهدي،",
      "chapter": 2,
      "verse": 5
    },
    {
      "text_ar": "لكي تجلبوا عليهم الخزي، وعلى أمهم الهلاك، لئلا يكون لهم نسل.",
      "chapter": 2,
      "verse": 6
    },
    {
      "text_ar": "ليتبددوا بين الأمم، ولتُمحَ أسماؤهم من الأرض، لأنهم احتقروا عهدي.",
      "chapter": 2,
      "verse": 7
    },
    {
      "text_ar": "ويل لك يا أشور، يا من تخفي الأثمة معك! أيتها الأمة الشريرة، اذكروا ما فعلتُ بسدوم وعمورة،",
      "chapter": 2,
      "verse": 8
    },
    {
      "text_ar": "اللتين أرضهما كتل من القار وكميات من الرماد. هذا ما سأفعله أيضاً بالذين لم يسمعوا لي»، يقول الرب القدير.",
      "chapter": 2,
      "verse": 9
    },
    {
      "text_ar": "يقول الرب لعزرا: «أخبر شعبي أني سأعطيهم ملكوت أورشليم، الذي كنت سأعطيه لإسرائيل.",
      "chapter": 2,
      "verse": 10
    },
    {
      "text_ar": "وسأسترد مجدهم لنفسي، وأعطي هؤلاء المظال الأبدية التي كنت قد أعددتها لهم.",
      "chapter": 2,
      "verse": 11
    },
    {
      "text_ar": "سيكون لهم شجرة الحياة عطراً ذكياً. لن يتعبوا ولن يكلوا.",
      "chapter": 2,
      "verse": 12
    },
    {
      "text_ar": "اطلبوا فتأخذوا. صلوا لكي تكون أيامكم قليلة ولكي تُقصر. الملكوت مُعَدّ لكم بالفعل. اسهروا!",
      "chapter": 2,
      "verse": 13
    },
    {
      "text_ar": "أشهدوا السماء والأرض. ادعوهما شهوداً، لأني أزلت الشر وخلقت الخير، لأني حي أنا، يقول الرب.",
      "chapter": 2,
      "verse": 14
    },
    {
      "text_ar": "«أيتها الأم، احتضني أولادك. سأخرجهم بفرح كحمامة تفعل. ثبتي أقدامهم، لأني قد اخترتك، يقول الرب.",
      "chapter": 2,
      "verse": 15
    },
    {
      "text_ar": "سأقيم الموتى من أمكنتهم، وأخرجهم من قبورهم، لأني أعترف باسمي فيهم.",
      "chapter": 2,
      "verse": 16
    },
    {
      "text_ar": "لا تخافي يا أم الأولاد، لأني قد اخترتك، يقول الرب.",
      "chapter": 2,
      "verse": 17
    },
    {
      "text_ar": "لمساعدتك، سأرسل عبديّ إشعياء وأرميا، اللذين بحسب مشورتهما قدسْتُ وأعددتُ لك اثنتي عشرة شجرة مثقلة بمختلف الثمار،",
      "chapter": 2,
      "verse": 18
    },
    {
      "text_ar": "وعددًا مماثلاً من الينابيع الجارية باللبن والعسل، وسبعة جبال عظيمة تنبت وروداً وأبصاقاً، والتي بها سأملأ أطفالك فرحاً.",
      "chapter": 2,
      "verse": 19
    },
    {
      "text_ar": "أحسنوا إلى الأرملة. أنصفوا اليتيم. أعطوا الفقير. دافعوا عن اليتيم. ألبسوا العريان.",
      "chapter": 2,
      "verse": 20
    }
  ]
}
